   assert.match(cli(file, 'list').out, /Cloud backup\s+€119\.99 yearly\s+€9\.99 a month/);
 }));

+test('add, list and total for weekly plans', () => withFile((file) => {
+  assert.equal(cli(file, 'add', 'Meal kit', '59.90', '--every', 'week', '--since', '2026-10-24').code, 0);
